#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024

int main(int argc, char *argv[])
{
    const char *msg_pal   = "PALINDROME";
    const char *msg_not   = "NOT_PALINDROME";
    const char *msg_long  = "TOO_LONG";

    const char *input = "";
    if (argc > 1) {
        input = argv[1];
    }

    size_t in_len = strlen(input);
    if (in_len > MAX_LEN) {
        puts(msg_long);
        return 0;
    }

    char norm[MAX_LEN + 1];
    size_t n = 0;
    for (size_t i = 0; i < in_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)tolower(c);
        }
    }
    norm[n] = '\0';

    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? msg_pal : msg_not);
    return 0;
}
